def fm(t):
    ms = int(round(t * 1000)); return f"{ms//3600000:02d}:{ms//60000%60:02d}:{ms//1000%60:02d},{ms%1000:03d}"
for k, lang in ((2, 'it'), (3, 'en')):
    prev = 0
    with open(f'projects/coir/sottotitoli/VociVere_coir_long.{lang}.srt', 'w', encoding='utf-8') as f:
        for i, row in enumerate(S, 1):
            a, b = row[0], row[1]; assert a >= prev - 0.01 and b > a, row; prev = b
            f.write(f"{i}\n{fm(a)} --> {fm(b)}\n{row[k]}\n\n")
print(len(S), 'sottotitoli')
